/**
 * Lets a signed-in user verify their phone actually pops up an OS-level
 * notification. Sends to every subscription endpoint registered for the
 * caller. Per-user rate limited so a misbehaving client cannot spam
 * their own devices.
 * @summary Send a sample push notification to the calling user's subscribed devices
 */
export const SendPushTestResponse = zod.object({
  delivered: zod
    .number()
    .int()
    .describe(
      "Number of subscription endpoints the test push was dispatched to",
    ),
});

/**
 * Upserts on the globally-unique device token: if the same physical device token was previously registered under a different account, ownership transfers to the current authenticated user (the correct behavior when a device logs out and a different user logs in).
 * @summary Register (or transfer ownership of) a native push device token
 */
export const registerNativePushDeviceBodyTokenMin = 20;
export const registerNativePushDeviceBodyTokenMax = 4096;

export const RegisterNativePushDeviceBody = zod.object({
  token: zod
    .string()
    .min(registerNativePushDeviceBodyTokenMin)
    .max(registerNativePushDeviceBodyTokenMax),
  platform: zod.enum(["android", "ios"]),
});

export const RegisterNativePushDeviceResponse = zod.object({
  message: zod.string(),
});

/**
 * Native-channel equivalent of POST /push/test. Sends one sample
 * notification through the exact `sendNativePushToUser` code path
 * production uses, so a passing result is real proof the FCM HTTP v1
 * wiring works. Authenticated + per-user rate limited. Does not accept
 * a device token or a URL from the request body. Unlike /push/test,
 * the outcome reflects FCM's per-message acceptance — see
 * NativePushTestResult.
 * @summary Send a sample FCM push to the caller's own registered mobile devices
 */
export const sendNativePushTestResponseTargetedMin = 0;

export const sendNativePushTestResponseAcceptedMin = 0;

export const SendNativePushTestResponse = zod
  .object({
    targeted: zod
      .number()
      .int()
      .min(sendNativePushTestResponseTargetedMin)
      .describe("Number of registered mobile device tokens targeted"),
    accepted: zod
      .number()
      .int()
      .min(sendNativePushTestResponseAcceptedMin)
      .describe("Number of messages accepted by FCM"),
    failures: zod
      .array(zod.enum(["unregistered", "auth", "invalid", "network"]))
      .describe("Failure category for each message not accepted by FCM"),
  })
  .describe(
    "Result of submitting a native push test to FCM. accepted confirms provider acceptance only; it is not proof that an OS notification was displayed on a device.",
  );

/**
 * @summary Remove the caller's own native push device registration
 */
export const unregisterNativePushDeviceBodyTokenMin = 20;
export const unregisterNativePushDeviceBodyTokenMax = 4096;

export const UnregisterNativePushDeviceBody = zod.object({
  token: zod
    .string()
    .min(unregisterNativePushDeviceBodyTokenMin)
    .max(unregisterNativePushDeviceBodyTokenMax),
});

export const UnregisterNativePushDeviceResponse = zod.object({
  message: zod.string(),
});

